inputs.script:
const slug=JSON.parse(sessionStorage.getItem('__rzn_co_slug')||'null');
if(!slug)throw new Error('Missing company slug');
const path='/company/'+encodeURIComponent(slug)+'/about/';
const link=[...document.querySelectorAll('a[href]')].find(a=>{try{return new URL(a.href,location.origin).pathname.replace(/\/$/,'')===path.replace(/\/$/,'');}catch(e){return false;}});
if(link)link.click();else setTimeout(()=>location.assign('https://www.linkedin.com'+path),0);
return {tab:'about',url:'https://www.linkedin.com'+path};

const slug=JSON.parse(sessionStorage.getItem('__rzn_co_slug')||'null');
if(!slug)throw new Error('Missing company slug');
const path='/company/'+encodeURIComponent(slug)+'/people/';
const link=[...document.querySelectorAll('a[href]')].find(a=>{try{return new URL(a.href,location.origin).pathname.replace(/\/$/,'')===path.replace(/\/$/,'');}catch(e){return false;}});
if(link)link.click();else setTimeout(()=>location.assign('https://www.linkedin.com'+path),0);
return {tab:'people',url:'https://www.linkedin.com'+path};

const slug=JSON.parse(sessionStorage.getItem('__rzn_co_slug')||'null');
if(!slug)throw new Error('Missing company slug');
const path='/company/'+encodeURIComponent(slug)+'/posts/';
const link=[...document.querySelectorAll('a[href]')].find(a=>{try{return new URL(a.href,location.origin).pathname.replace(/\/$/,'')===path.replace(/\/$/,'');}catch(e){return false;}});
if(link)link.click();else setTimeout(()=>location.assign('https://www.linkedin.com'+path),0);
return {tab:'posts',url:'https://www.linkedin.com'+path};

const N=s=>String(s||'').replace(/\s+/g,' ').trim();
const CAP=Math.max(1,Math.min(50,parseInt(arg0,10)||10));
const count=s=>{const m=N(s).replace(/,/g,'').match(/(\d+(?:\.\d+)?)\s*([KMB])?/i);return m?Math.round(Number(m[1])*({K:1e3,M:1e6,B:1e9}[(m[2]||'').toUpperCase()]||1)):0;};
const posts=new Map();const textKeys=new Map();
const menus='button[aria-label^="Open control menu for post by "]';
const legacy='[data-urn^="urn:li:activity:"],[data-id^="urn:li:activity:"]';
const boxSelector='[data-testid="expandable-text-box"],.update-components-text';
const cardOf=el=>{let card=el;for(let i=0;card&&i<20;i++,card=card.parentElement){if(card.querySelector(boxSelector)&&card.querySelector('button[aria-label="Comment"],.social-actions-button.comment-button'))return card;}return null;};
const collect=()=>{
 for(const seed of document.querySelectorAll(menus+','+legacy)){
  const el=cardOf(seed);if(!el)continue;
  const box=el.querySelector(boxSelector);const text=N(box&&box.innerText);if(!text)continue;
  const menu=el.querySelector(menus);const author=menu?N(menu.getAttribute('aria-label')):'';
  const links=[...el.querySelectorAll('a[href]')];
  const permalink=links.find(a=>/\/feed\/update\/urn:li:(activity|share):|\/posts\/.*activity-\d+/.test(a.href));
  const attr=el.getAttribute('data-urn')||el.getAttribute('data-id')||seed.getAttribute('data-urn')||seed.getAttribute('data-id')||'';
  const match=(attr+' '+(permalink?permalink.href:'')).match(/urn:li:(?:activity|share):\d+|activity-(\d+)/);
  const urn=match?(match[1]?'urn:li:activity:'+match[1]:match[0]):'';
  const post_url=permalink?permalink.href.split('?')[0]:(urn?'https://www.linkedin.com/feed/update/'+urn+'/':'');
  const key=textKeys.get(text)||urn||post_url||author+'\n'+text;
  const labels=[...el.querySelectorAll('[aria-label]')].map(e=>e.getAttribute('aria-label')||'');
  const flat=N(el.innerText);
  // Current cards can expose a bare reaction total instead of a labelled count.
  const bare=[...el.querySelectorAll('button,span')].find(e=>{const t=N(e.innerText);return /^[\d,.]+\s*[KMB]?$/i.test(t)&&!box.contains(e)&&(box.compareDocumentPosition(e)&Node.DOCUMENT_POSITION_FOLLOWING)&&!/(comment|repost)/i.test(e.getAttribute('aria-label')||e.parentElement&&e.parentElement.getAttribute('aria-label')||'');});
  const metric=word=>{const re=new RegExp('([\\d,.]+\\s*[KMB]?)\\s+'+word+'s?\\b','i');for(const label of labels){const m=label.match(re);if(m)return count(m[1]);}const m=flat.match(re);return m?count(m[1]):0;};
  const reactionEl=el.querySelector('.social-details-social-counts__reactions-count,[data-testid="social-actions-reactions-count"]');
  const time=el.querySelector('time');
  const age=N(time&&(time.innerText||time.getAttribute('datetime')))||((flat.match(/\b\d+\s*(?:minutes?|hours?|days?|weeks?|months?|years?)\s+ago\b|\b\d+\s*(?:mo|[mhdwy])\b/i)||[])[0]||'');
  const am=age.match(/(\d+)\s*(mo|minutes?|hours?|days?|weeks?|months?|years?|[mhdwy])\b/i);
  const units={m:1/1440,h:1/24,d:1,w:7,mo:30,y:365};
  const age_days=am?Math.round(Number(am[1])*(units[am[2].toLowerCase()]||units[/^month/i.test(am[2])?'mo':am[2][0].toLowerCase()])*10)/10:-1;
  const post={post_url:post_url,urn:urn,is_repost:/reposted this/i.test(flat.slice(0,200)),posted:age,age_days:age_days,text:text.slice(0,1200),reactions:metric('reaction')||count(reactionEl&&reactionEl.innerText)||count(bare&&bare.innerText),comments:metric('comment'),reposts:metric('repost')};
  if(posts.has(key)||posts.size<CAP){const old=posts.get(key);if(old){post.urn=post.urn||old.urn;post.post_url=post.post_url||old.post_url;}posts.set(key,post);textKeys.set(text,key);}
 }
};
for(let i=0;i<=24;i++){
 collect();if(posts.size>=CAP||i===24)break;
 window.scrollBy(0,Math.max(500,Math.round(window.innerHeight*0.8)));
 await new Promise(resolve=>setTimeout(resolve,1500));
}
const list=[...posts.values()];
const about=JSON.parse(sessionStorage.getItem('__rzn_co_about')||'{}');
const out={posts:list,posts_fetched:list.length,posts_last_30_days:list.filter(p=>p.age_days>=0&&p.age_days<=30).length,followers:about.followers||0,posts_url:location.href};
sessionStorage.setItem('__rzn_co_posts',JSON.stringify(out));return out;
